/**
 * Recursively flattens a nested object into a flat object with dot-notation keys
 * @param ob - The object to flatten
 * @returns A flattened object with dot-notation keys
 * @example
 * flattenObject({ a: { b: 'value' } }) // returns { 'a.b': 'value' }
 * flattenObject({ user: { name: 'John', address: { city: 'NYC' } } })
 * // returns { 'user.name': 'John', 'user.address.city': 'NYC' }
 */
export declare const flattenObject: (ob: any) => Record<string, string>;
